from fastapi import FastAPI, Request, Form, HTTPException
from fastapi.responses import HTMLResponse, RedirectResponse
from pydantic import BaseModel
import sqlite3
import uuid
import datetime

app = FastAPI()

DB = "payledger.db"

# DB init
def init():
    con = sqlite3.connect(DB)
    c = con.cursor()
    c.execute(
        """CREATE TABLE IF NOT EXISTS payments 
        (id TEXT PRIMARY KEY, user TEXT, amount INTEGER, currency TEXT, status TEXT, paidat TEXT, target TEXT)"""
    )
    c.execute(
        """CREATE TABLE IF NOT EXISTS users 
        (username TEXT PRIMARY KEY, pw TEXT)"""
    )
    con.commit()
    con.close()

init()

class PaymentCreate(BaseModel):
    user: str
    amount: int
    currency: str
    target: str

@app.post("/api/register")
def register(username: str = Form(...), pw: str = Form(...)):
    con = sqlite3.connect(DB)
    c = con.cursor()
    try:
        c.execute("INSERT INTO users VALUES (?,?)", (username, pw))
        con.commit()
    except sqlite3.IntegrityError:
        raise HTTPException(status_code=400, detail="Felhasználónév már létezik!")
    finally:
        con.close()
    return {"ok": True}

@app.post("/api/login")
def login(username: str = Form(...), pw: str = Form(...)):
    con = sqlite3.connect(DB)
    c = con.cursor()
    c.execute("SELECT * FROM users WHERE username=? AND pw=?", (username, pw))
    ok = c.fetchone()
    con.close()
    if not ok:
        raise HTTPException(status_code=400, detail="Hibás adat!")
    return {"ok": True}

@app.post("/api/make_paymentlink")
def make_paymentlink(pay: PaymentCreate):
    payid = str(uuid.uuid4())
    now = datetime.datetime.utcnow().isoformat()
    con = sqlite3.connect(DB)
    c = con.cursor()
    c.execute(
        "INSERT INTO payments VALUES (?,?,?,?,?,NULL,?)",
        (payid, pay.user, pay.amount, pay.currency.upper(), "pending", pay.target),
    )
    con.commit()
    con.close()
    return {"payment_url": f"/pay/{payid}"}

@app.get("/pay/{payid}", response_class=HTMLResponse)
def payform(payid: str):
    con = sqlite3.connect(DB)
    c = con.cursor()
    c.execute("SELECT id, amount, currency, target, status FROM payments WHERE id=?", (payid,))
    row = c.fetchone()
    con.close()
    if not row:
        return HTMLResponse("Nincs ilyen fizetés!", status_code=404)
    return f"""
    <h2>Fizetés</h2>
    <div>Fizetendő: <b>{row[1]} {row[2]}</b></div>
    <form action="/api/pay/{payid}" method="post">
        <input required name="payer" placeholder="Az ön neve v. email">
        <button type="submit">Fizetek (DEMO - instant ledger)</button>
    </form>
    """

@app.post("/api/pay/{payid}")
def pay(payid: str, payer: str = Form(...)):
    con = sqlite3.connect(DB)
    c = con.cursor()
    c.execute(
        "UPDATE payments SET status=?, paidat=? WHERE id=?",
        ("paid", datetime.datetime.utcnow().isoformat(), payid),
    )
    con.commit()
    con.close()
    return RedirectResponse(f"/paid/{payid}", status_code=303)

@app.get("/paid/{payid}", response_class=HTMLResponse)
def paidmsg(payid: str):
    return f"""
    <h2>Fizetés sikeres!</h2>
    <div>Köszönjük – tranzakció rögzítve (DEMO ledger, azonnali státuszfrissítés).</div>
    """

@app.get("/api/payment_status/{payid}")
def status(payid: str):
    con = sqlite3.connect(DB)
    c = con.cursor()
    c.execute("SELECT status FROM payments WHERE id=?", (payid,))
    row = c.fetchone()
    con.close()
    return {"status": row[0] if row else "nincs"}


