      let fd = new FormData(e.target);
      let data = {};
      fd.forEach((v, k) => data[k] = v);
      let r = await fetch('/api/make_paymentlink', {
        method:'POST', body:fd
      });
      let out = await r.json();
      document.getElementById("plink_out").innerHTML =
        "Fizetési link: <a href='" + out.payment_url + "' target='_blank'>" + out.payment_url + "</a>";
    };
